8	namespace TutorFlow.Tests;
9	
10	/// <summary>
11	/// RN-09 / CA-09: un cuerpo con bytes que no son UTF-8 válido dentro de una cadena JSON es entrada inválida: 400 con
12	/// {"error":...}, nunca 503 ni 500; queda auditado con código 400 y tokens 0, y no se llama al modelo.
13	/// Los bytes inválidos son crudos (no escapes \u).
14	/// </summary>
15	public class Utf8InvalidoTests
16	{
17	    private const string Cita = "{\"documento\":\"reglamento-prueba.md\",\"seccion\":\"Nota mínima\"}";
18	    private const string Marcador = "MARCADOR-SECRETO-QZ81";
19	
20	    private static LlmFuncion ModeloOk() => new((_, _) => Task.FromResult(new LlmRespuesta(
21	        "{\"respuesta\":\"ok\",\"citas\":[" + Cita + "]}", [], new LlmUso(7, 3))));
22	
23	    private static byte[] Ascii(string s) => Encoding.ASCII.GetBytes(s);
24	
25	    private static byte[] Unir(params byte[][] partes) => partes.SelectMany(p => p).ToArray();
26	
27	    private static async Task<(HttpStatusCode Codigo, string Cuerpo)> Enviar(EntornoAuditoria e, byte[] cuerpo)
28	    {
29	        var content = new ByteArrayContent(cuerpo);
30	        content.Headers.ContentType = new MediaTypeHeaderValue("application/json");
31	        var r = await e.Cliente.PostAsync(EntornoAuditoria.Url, content);
32	        return (r.StatusCode, await r.Content.ReadAsStringAsync());
33	    }
34	
35	    private static async Task Verifica400(EntornoAuditoria e, LlmFuncion llm, HttpStatusCode c, string cuerpo)
36	    {
37	        Assert.Equal(HttpStatusCode.BadRequest, c);
38	        using var d = JsonDocument.Parse(cuerpo);
39	        Assert.Equal(JsonValueKind.String, d.RootElement.GetProperty("error").ValueKind);
40	        Assert.DoesNotContain(Marcador, cuerpo);
41	        Assert.DoesNotContain("respuesta", cuerpo);
42	        Assert.Equal(0, llm.Llamadas);
43	
44	        var l = await e.UnaLinea();   // JSON válido, una sola línea
45	        AssertForma(l);
46	        Assert.Equal(400, Codigo(l));
47	        Assert.Equal(0, Tokens(l));
48	        Assert.Equal(0d, Costo(l));
49	        Assert.Empty(Estudiantes(l));
50	    }
51	
52	    [Fact]
53	    public async Task ESC_09_UTF8_pregunta_latin1_bytes_sueltos_0xBF_0xF3_da_400()
54	    {
55	        var llm = ModeloOk();
56	        using var e = new EntornoAuditoria(llm);
57	        // "¿Cómo" en Latin-1: BF 43 F3 6D 6F
58	        var cuerpo = Unir(Ascii("{\"pregunta\":\"" + Marcador + " "), [0xBF, (byte)'C', 0xF3, (byte)'m', (byte)'o'],
59	            Ascii(" funciona?\",\"usuario\":{\"rol\":\"estudiante\",\"id\":\"T-E1\"}}"));
60	        var (c, b) = await Enviar(e, cuerpo);
61	        await Verifica400(e, llm, c, b);
62	    }
63	
