65	    public async Task ESC_09_UTF8_rol_con_byte_invalido_da_400()
66	    {
67	        var llm = ModeloOk();
68	        using var e = new EntornoAuditoria(llm);
69	        var cuerpo = Unir(Ascii("{\"pregunta\":\"" + Marcador + "\",\"usuario\":{\"rol\":\"estu"), [0xE9],
70	            Ascii("diante\",\"id\":\"T-E1\"}}"));
71	        var (c, b) = await Enviar(e, cuerpo);
72	        await Verifica400(e, llm, c, b);
73	    }
