80	        var cuerpo = Unir(Ascii("{\"pregunta\":\"" + Marcador + "\",\"usuario\":{\"rol\":\"estudiante\",\"id\":\"T-"), [0xE9],
81	            Ascii("1\"}}"));
82	        var (c, b) = await Enviar(e, cuerpo);
83	        await Verifica400(e, llm, c, b);
84	    }
85	
86	    [Fact]
87	    public async Task ESC_09_UTF8_secuencia_truncada_0xC3_al_final_de_la_cadena_da_400()
88	    {
89	        var llm = ModeloOk();
90	        using var e = new EntornoAuditoria(llm);
91	        var cuerpo = Unir(Ascii("{\"pregunta\":\"" + Marcador + " fin"), [0xC3],
92	            Ascii("\",\"usuario\":{\"rol\":\"estudiante\",\"id\":\"T-E1\"}}"));
93	        var (c, b) = await Enviar(e, cuerpo);
94	        await Verifica400(e, llm, c, b);
95	    }
