109	    public async Task ESC_09_UTF8_nunca_5xx_en_ninguna_posicion_del_byte_invalido()
110	    {
111	        var llm = ModeloOk();
112	        using var e = new EntornoAuditoria(llm);
113	        var plantillas = new[]
114	        {
115	            (Pre: "{\"pregunta\":\"a", Pos: "\",\"usuario\":{\"rol\":\"estudiante\",\"id\":\"T-E1\"}}"),
116	            (Pre: "{\"pregunta\":\"a\",\"usuario\":{\"rol\":\"est", Pos: "\",\"id\":\"T-E1\"}}"),
117	            (Pre: "{\"pregunta\":\"a\",\"usuario\":{\"rol\":\"estudiante\",\"id\":\"T", Pos: "\"}}"),
118	        };
119	        foreach (var (pre, pos) in plantillas)
120	            foreach (var malo in new byte[][] { [0xBF], [0xF3], [0xFF], [0xC3], [0xC0, 0x80], [0xED, 0xA0, 0x80] })
121	            {
122	                var (c, b) = await Enviar(e, Unir(Ascii(pre), malo, Ascii(pos)));
123	                Assert.True(c == HttpStatusCode.BadRequest, $"{pre}[{Convert.ToHexString(malo)}] dio {(int)c}: {b}");
124	                Assert.Contains("\"error\"", b);
125	            }
126	        Assert.Equal(0, llm.Llamadas);
127	        var lineas = await e.LineasCrudas(plantillas.Length * 6);
