138	    /// valida el UTF-8 de las cadenas hasta que se leen con GetString; la propiedad desconocida nunca se lee, así que la
139	    /// petición se procesa como válida (200, modelo llamado una vez). No hay fuga: el valor ignorado no llega a la
140	    /// respuesta ni a la auditoría. Si esto cambiara a 400 (validación estricta del cuerpo), la prueba debe revisarse a
141	    /// conciencia, no ajustarse en silencio.
142	    /// </summary>
143	    [Fact]
144	    public async Task ESC_09_UTF8_byte_invalido_solo_en_propiedad_desconocida_se_ignora_y_da_200_documentado()
145	    {
146	        var llm = ModeloOk();
147	        using var e = new EntornoAuditoria(llm);
148	        var cuerpo = Unir(Ascii("{\"extra\":\"" + Marcador + " "), [0xBF, 0xF3],
149	            Ascii("\",\"pregunta\":\"Hola\",\"usuario\":{\"rol\":\"estudiante\",\"id\":\"T-E1\"}}"));
150	        var (c, b) = await Enviar(e, cuerpo);
151	        Assert.Equal(HttpStatusCode.OK, c);
152	        Assert.DoesNotContain(Marcador, b);
153	        Assert.Equal(1, llm.Llamadas);
154	        var l = await e.UnaLinea();
155	        AssertForma(l);
156	        Assert.Equal(200, Codigo(l));
157	        Assert.DoesNotContain(Marcador, e.TextoAuditoria());
158	    }
159	
160	    // ---------- Control ----------
161	
162	    [Fact]
163	    public async Task ESC_09_UTF8_control_el_mismo_cuerpo_en_utf8_correcto_da_200()
164	    {
165	        var llm = ModeloOk();
166	        using var e = new EntornoAuditoria(llm);
167	        var json = "{\"pregunta\":\"¿Cómo funciona la nota mínima?\",\"usuario\":{\"rol\":\"estudiante\",\"id\":\"T-E1\"}}";
168	        var (c, b) = await Enviar(e, new UTF8Encoding(false).GetBytes(json));
169	        Assert.Equal(HttpStatusCode.OK, c);
170	        using var d = JsonDocument.Parse(b);
171	        Assert.Equal("ok", d.RootElement.GetProperty("respuesta").GetString());
172	        Assert.Equal(1, llm.Llamadas);
173	        var l = await e.UnaLinea();
174	        Assert.Equal(200, Codigo(l));
175	        Assert.Equal("¿Cómo funciona la nota mínima?", Texto(l, "pregunta"));
176	    }
