167	        var json = "{\"pregunta\":\"¿Cómo funciona la nota mínima?\",\"usuario\":{\"rol\":\"estudiante\",\"id\":\"T-E1\"}}";
168	        var (c, b) = await Enviar(e, new UTF8Encoding(false).GetBytes(json));
169	        Assert.Equal(HttpStatusCode.OK, c);
170	        using var d = JsonDocument.Parse(b);
171	        Assert.Equal("ok", d.RootElement.GetProperty("respuesta").GetString());
172	        Assert.Equal(1, llm.Llamadas);
173	        var l = await e.UnaLinea();
174	        Assert.Equal(200, Codigo(l));
175	        Assert.Equal("¿Cómo funciona la nota mínima?", Texto(l, "pregunta"));
176	    }
177	}
