    {
        var cfg = new Dictionary<string, string?> { ["Datos:Ruta"] = Fabrica.RutaFixtures, ["LLM_API_KEY"] = llave ?? "" };
        if (proveedor != null) cfg["LLM_PROVIDER"] = proveedor;
