19	/// <summary>Manejador HTTP falso del cliente "llm": registra cada petición y devuelve respuestas guionadas. Nunca usa red.</summary>
20	public sealed class ProveedorHttpFalso : HttpMessageHandler
21	{
22	    private readonly Queue<Func<PeticionRegistrada, HttpResponseMessage>> _pasos = new();
23	    public List<PeticionRegistrada> Peticiones { get; } = [];
24	    public int Cuenta { get { lock (Peticiones) return Peticiones.Count; } }
25	
26	    public ProveedorHttpFalso Responde(HttpStatusCode codigo, string cuerpo, string tipo = "application/json")
27	    {
28	        _pasos.Enqueue(_ => new HttpResponseMessage(codigo) { Content = new StringContent(cuerpo, Encoding.UTF8, tipo) });
29	        return this;
30	    }
31	
32	    public ProveedorHttpFalso Ok(string cuerpo) => Responde(HttpStatusCode.OK, cuerpo);
33	
34	    public ProveedorHttpFalso Lanza(Exception e) { _pasos.Enqueue(_ => throw e); return this; }
35	
36	    protected override async Task<HttpResponseMessage> SendAsync(HttpRequestMessage request, CancellationToken ct)
37	    {
38	        var cab = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
39	        foreach (var h in request.Headers) cab[h.Key] = string.Join(",", h.Value);
40	        string cuerpo = "";
41	        if (request.Content != null)
42	        {
43	            foreach (var h in request.Content.Headers) cab[h.Key] = string.Join(",", h.Value);
44	            cuerpo = await request.Content.ReadAsStringAsync(ct);
45	        }
46	        var reg = new PeticionRegistrada(request.Method.Method, request.RequestUri!.ToString(), cab, cuerpo);
47	        Func<PeticionRegistrada, HttpResponseMessage> paso;
48	        lock (Peticiones)
49	        {
50	            Peticiones.Add(reg);
51	            if (_pasos.Count == 0) throw new InvalidOperationException("Guion del proveedor falso agotado.");
52	            paso = _pasos.Dequeue();
53	        }
54	        return paso(reg);
55	    }
56	}
