48	    /// <param name="rutaAuditoria">Ruta de auditoría; por defecto un archivo temporal único.</param>
49	    public EntornoAuditoria(ILlmClient? llm, IDictionary<string, string?>? config = null, string llave = Llave,
50	        string? rutaAuditoria = null, Action<IConfigurationBuilder>? configurar = null)
51	    {
52	        RutaAuditoria = rutaAuditoria ?? Path.Combine(Path.GetTempPath(), "tf-audit-" + Guid.NewGuid().ToString("N") + ".jsonl");
53	        var cfg = new Dictionary<string, string?>
54	        {
55	            ["Datos:Ruta"] = Fabrica.RutaFixtures,
56	            ["LLM_API_KEY"] = llave,
57	            ["Auditoria:Ruta"] = RutaAuditoria,
58	        };
59	        if (config != null) foreach (var (k, v) in config) cfg[k] = v;
60	
61	        _fabrica = new WebApplicationFactory<Program>().WithWebHostBuilder(b =>
62	        {
63	            foreach (var (k, v) in cfg) b.UseSetting(k, v);
64	            b.ConfigureAppConfiguration((_, c) => { c.AddInMemoryCollection(cfg); configurar?.Invoke(c); });
65	            b.ConfigureServices(sv => sv.AddLogging(l => { l.SetMinimumLevel(LogLevel.Trace); l.AddProvider(Logs); }));
66	            b.ConfigureTestServices(sv =>
67	            {
68	                sv.AddHttpClient("llm").ConfigurePrimaryHttpMessageHandler(() => (HttpMessageHandler)Proveedor);
69	                if (llm != null)
70	                {
71	                    sv.RemoveAll<ILlmClient>();
72	                    sv.AddSingleton(llm);
73	                }
74	            });
75	        });
76	        // CreateClient arranca el host: una configuración inválida (p. ej. precios) lanza aquí.
77	        Cliente = _fabrica.CreateClient();
78	        Cliente.Timeout = TimeSpan.FromSeconds(60);
79	    }
