            await Task.Delay(100);
            lineas = TextoAuditoria().Split('\n').Select(l => l.TrimEnd('\r')).Where(l => l.Length > 0).ToList();
            Assert.Single(lineas);
            return JsonDocument.Parse(lineas[0]).RootElement.Clone();
        }

