    [Theory]
    [InlineData(HttpStatusCode.BadRequest)]
    [InlineData(HttpStatusCode.Unauthorized)]
    public async Task ESC_05_7_principal_400_o_401_no_salta_al_respaldo_y_da_503(HttpStatusCode codigoPrincipal)
    {
